team = player.info.team                     // PlayerState+0x930
if team >= 2 { panic_bounds_check(team, 2) }// player_champion 의 팀축 길이 2
pos   = player.info.position as index       // PlayerState+0x9c0, 0..=4 (Top/Jungle/Mid/Bottom/Support)
cache = *data.cache                         // &AbstractGameWithCache
champ = cache.player_champion[team][pos]    // 0x1e0 + team*40 + pos*8
        .unwrap()                           // None 이면 core::option::unwrap_failed 로 패닉
map   = data.context.map                    // data+0x8 -> GameContext+0x20
(lx, ly, rx, ry) = map.fountains[team]      // MapDef+0x6d70 + team*32   [line 37]

// [line 38] 샘(회복지역) 안에 있는가 — IR 은 x축 → y축 순으로 단락평가
is_in_heal_area =  champ.x >= lx && champ.x <= rx     // Entity+0x660
                && champ.y >= ly && champ.y <= ry     // Entity+0x668

// [line 41] 샘 안 + 만피가 아니면 회복 계속
if is_in_heal_area && champ.hp < champ.stat_cached.hp {   // +0x670 < +0x628
    return SubPlan::Recall                  // tag 5, 페이로드 ZST(태그만 store)
}

// [line 45] 적 팀의 쌍둥이타워(억제기 격)가 아직 남아 있는가
has_enemy_twin_tower = !cache.twin_towers[1 - team].is_empty()   // 0x130 + (1-team)*32, len@+0x18

// [line 47~48] 남아 있으면 넥서스를 못 치므로 자기 라인을 '푸시'하는 라인전으로 대체
if has_enemy_twin_tower {
    return SubPlan::LineDefense(LineDefenseSubPlan{
        style:              LineStyle::Aggressive,       // 0 -> ret+0x8
        line:               self.line,                   // AttackNexusPlan+0x8 -> ret+0x9
        minion_action_type: MinionActionType::Push,      // 2 -> ret+0xa
    })                                                   // tag 2
}

// [line 52] 적 쌍둥이타워가 전멸했다 = 넥서스 강타
return SubPlan::AttackNexus                 // tag 16, 페이로드 ZST

